-- LemmaYard problem catalog for Supabase, part 1 of 6 (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- The same catalog in one file is docs/supabase/problems.sql; the parts exist for SQL
-- editors that refuse a large paste. Run all 6 parts, in any order, after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). Each part is its own transaction
-- over 8 problems, 13 tags and 1341 test cases (catalog: 50 problems,
-- 6625 test cases). It writes the same rows as `pnpm problems:import`: upsert by
-- slug (published), tags, and a full replacement of each problem's tags and test cases.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (26, 27, 31, 36, 41, 50, 5, 6)
    AND "slug" NOT IN ($ly$alarm-streak$ly$, $ly$anagram-families$ly$, $ly$back-to-back-talks$ly$, $ly$balanced-vote-stretches$ly$, $ly$banner-widths$ly$, $ly$best-hub-town$ly$, $ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$alarm-streak$ly$, $ly$anagram-families$ly$, $ly$back-to-back-talks$ly$, $ly$balanced-vote-stretches$ly$, $ly$banner-widths$ly$, $ly$best-hub-town$ly$, $ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$array$ly$, $ly$Array$ly$),
  ($ly$sliding-window$ly$, $ly$Sliding Window$ly$),
  ($ly$string$ly$, $ly$String$ly$),
  ($ly$hash-table$ly$, $ly$Hash Table$ly$),
  ($ly$sorting$ly$, $ly$Sorting$ly$),
  ($ly$greedy$ly$, $ly$Greedy$ly$),
  ($ly$prefix-sum$ly$, $ly$Prefix Sum$ly$),
  ($ly$stack$ly$, $ly$Stack$ly$),
  ($ly$monotonic-stack$ly$, $ly$Monotonic Stack$ly$),
  ($ly$tree$ly$, $ly$Tree$ly$),
  ($ly$depth-first-search$ly$, $ly$Depth First Search$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$binary-search$ly$, $ly$Binary Search$ly$)
ON CONFLICT ("slug") DO NOTHING;

-- ---- alarm-streak ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (26, $ly$alarm-streak$ly$, $ly$Alarm Streak$ly$, $ly$easy$ly$, $ly$A power substation logs its load once a minute in `load`. A monitor looks at
every block of `k` consecutive minutes: the block that starts at minute `s`
covers `load[s]` through `load[s + k - 1]`, and it **raises an alarm** when
the total load in the block is strictly greater than `limit`.

The operators want to know how long the worst alarm streak lasted: return the
largest number of consecutive start minutes `s, s + 1, ..., s + t - 1` whose
blocks all raise an alarm. Return `0` if no block raises an alarm, or if
`k` is larger than the number of readings (then there are no blocks at all).

## Constraints

- `0 <= load.length <= 10^5`
- `0 <= load[i] <= 10^6`
- `1 <= k <= 10^5`
- `0 <= limit <= 10^11`
$ly$, $ly${"name":"longestAlarmStreak","params":[{"name":"load","type":"int[]"},{"name":"k","type":"int"},{"name":"limit","type":"int"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1290)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
