  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$alarm-streak$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$alarm-streak$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$array$ly$, $ly$sliding-window$ly$);

