**families**: two words belong to the same family when one can be turned into
the other by rearranging its letters (so they use exactly the same letters the
same number of times). Every entry of `words` is a member of exactly one
family, and repeated entries are separate members of the same family.

Return an array of two numbers:

1. how many families have **at least two** members, and
2. the number of members in the largest family.

For an empty list return `[0, 0]`.

## Constraints

- `0 <= words.length <= 10^4`
- `1 <= words[i].length <= 20`
- `words[i]` contains only lowercase English letters.
$ly$, $ly${"name":"anagramFamilies","params":[{"name":"words","type":"string[]"}],"returns":"int[]"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1310)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$anagram-families$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$anagram-families$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$string$ly$, $ly$hash-table$ly$, $ly$sorting$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$anagram-families$ly$);
