-- ---- back-to-back-talks ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (31, $ly$back-to-back-talks$ly$, $ly$Back-to-Back Talks$ly$, $ly$easy$ly$, $ly$A one-day conference publishes its programme as `talks`, where
`talks[i] = [start, duration]`: talk `i` begins at minute `start` and lasts
`duration` minutes, so it occupies the half-open time span
`[start, start + duration)`. Talks may overlap because they run in different
halls.

A visitor wants to sit through as many talks as possible, each one from its
first to its last minute, and can be in only one hall at a time. Walking
between halls takes no time, so a talk may begin at exactly the minute the
previous one ends.

Return the largest number of talks the visitor can attend completely.

## Constraints

- `0 <= talks.length <= 10^5`
- `talks[i].length == 2`
- `0 <= start <= 10^9`
- `1 <= duration <= 10^9`
$ly$, $ly${"name":"maxTalks","params":[{"name":"talks","type":"int[][]"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1440)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$back-to-back-talks$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$back-to-back-talks$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$greedy$ly$, $ly$sorting$ly$);

