  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$balanced-vote-stretches$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$balanced-vote-stretches$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$string$ly$, $ly$prefix-sum$ly$, $ly$hash-table$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$balanced-vote-stretches$ly$);
