  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$binary-search$ly$);
